with d as (select value r from jsonb_array_elements($q$[{"notes":["Soak wooden skewers in water for 30 minutes before threading if using them instead of metal ones.","Make the suya spice ahead and store in an airtight container for up to two weeks.","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"steps":[{"text":"Thread the beef cubes onto skewers, packing them tightly together. Rub with oil, salt, black pepper and ground ginger."},{"text":"Pulse the roasted peanuts in a food processor until they're finely ground but still have some texture, not a smooth butter. Tip into a shallow bowl and stir through the cayenne, paprika, ground ginger, salt, black pepper and garlic."},{"text":"Heat a griddle, grill or large frying pan over high heat until very hot. Working in batches, sear the skewers for 3 to 4 minutes, turning to cook all sides until the beef is deeply browned and cooked through (the meat should reach 75°C inside)."},{"text":"Immediately after cooking, while still hot, roll each skewer in the suya spice mixture until generously coated on all sides."},{"text":"Serve hot, straight away."}],"id":"e2c7f28f-8f02-4b35-8926-daad7f65fde3"},{"notes":["A potjie needs at least 45 minutes on low, steady heat. If your braai is too hot, move the pot to the edge and add less frequent wood.","You can prep all the veg at home and bring it in containers to the braai for faster assembly.","Leftover potjiekos reheats beautifully the next day.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Place a 7-litre cast iron potjie (or large heavy-based pot) over medium coals on the braai. Heat the oil until shimmering, then add the beef in batches. Brown on all sides, about 8 minutes per batch, then remove and set aside."},{"text":"Reduce the heat to low coals (move the pot away from the hottest part of the braai). Add the onion to the pot and cook, stirring, for 3 minutes until slightly softened."},{"text":"Add the browned beef back to the pot, then layer in the carrots and potatoes. Sprinkle with garlic and thyme, then season with salt and pepper."},{"text":"Pour the beef stock over everything. Cover with the lid and let it cook on low heat for about 1 hour, until the potatoes and beef are almost tender. Resist lifting the lid too often, you want to keep the heat in."},{"text":"Add the cabbage wedges, nestling them into the liquid. Replace the lid and cook for another 20 minutes until the cabbage is tender and the beef is cooked through."},{"text":"Taste and adjust the seasoning. Serve straight from the pot, family-style, with crusty bread to soak up the liquid."}],"id":"ae27383a-1e21-43db-9d18-76006c448d7c"},{"notes":["Make the macaroni salad ahead: it's even better the next day.","If you can't find mirin, use 2 tbsp honey instead.","Leftover chicken keeps for three days in the fridge; reheat gently with a splash of water.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Cook the macaroni according to packet directions until al dente, then drain and rinse under cold water. In a bowl, mix the mayonnaise, rice vinegar, sugar, carrot, and onion. Toss the cooled pasta through. Season to taste with salt and pepper. Chill while you cook the chicken."},{"text":"In a small bowl, whisk together the soy sauce, brown sugar, mirin, garlic, and ginger. Set aside."},{"text":"Heat the oil in a large frying pan over medium-high heat. Season the chicken thighs with salt and pepper on both sides. Place skin-side down in the pan and cook for 6–7 minutes until the skin is golden and crispy."},{"text":"Turn the thighs skin-side up and cook for another 4–5 minutes until cooked through (internal temperature 75°C). Pour off most of the fat from the pan, leaving about 1 tbsp."},{"text":"Pour the teriyaki sauce over the chicken. Mix the cornflour with the water until smooth, add to the pan, and stir gently. Simmer for 2–3 minutes, stirring occasionally, until the sauce thickens and coats the chicken."},{"text":"Divide the rice between four plates, making two scoops per plate. Top with the glazed chicken thighs and any sauce. Serve the macaroni salad on the side and garnish with spring onion if you like."}],"id":"67eb5369-b9f4-4c2c-9247-f057a11adec1"},{"notes":["Perkedel is best served warm. You can make the fritters ahead and reheat them in a moderate oven (180°C) for 8 minutes.","Let the boiled potato cool completely, warm potato breaks down when you fry it and won't stay soft inside.","Serve with sambal or sweet soy sauce for dipping.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"c0013384-f85d-4c13-a55d-db259e428915"},{"diets":["vegetarian","vegan","no-gluten","no-dairy"],"id":"df1aad68-b793-4a1d-995e-ae3ba8771a26"},{"notes":["This keeps in the fridge for 3 days and tastes better the next day as the flavours deepen. Serve it cold as banchan or gently reheat.","You can use any dried chillies you have, guajillo or ancho work well too, though the flavour will shift. Stay with long varieties if you can; they soften into beautiful strands."],"id":"dfb1aa42-b9ad-4b0e-b149-93068436e0dd"},{"notes":["Lugaw keeps in the fridge for 2 days; reheat gently with a little extra stock to loosen it.","Add crispy fried garlic and egg just before serving so the garlic stays crunchy.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear."],"steps":[{"text":"Bring the chicken stock to a boil in a large pot until bubbling steadily. Add the rice and salt, stir well, and return to a boil."},{"text":"Reduce heat to low, cover partly, and simmer, stirring often, for 40 minutes. The rice should break down and the porridge should be creamy and thick."},{"text":"While the lugaw cooks, boil the eggs in a separate pot for 10 minutes until hard-boiled. Cool, shell, and halve them."},{"text":"Heat the neutral oil in a small frying pan over medium-high heat. Add the sliced garlic and fry, stirring, until golden and crispy, about 3 minutes. Drain on paper towel."},{"text":"Divide the lugaw among serving bowls. Top each with a halved egg, crispy fried garlic, and spring onion if using. Serve warm."}],"id":"fb592060-489a-4c14-8126-23f541d56f8d"},{"notes":["Make ahead: prepare the parcel up to 4 hours before roasting.","The cooking liquid makes a silky pan sauce, don't skip it. Serve with horta (simply boiled greens) or crusty bread to mop it up.","Leftovers shred beautifully and work in pies or as a filling for spanakopita.","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"steps":[{"text":"Pat the lamb dry and season generously inside and out with salt and pepper."},{"text":"Tear off a sheet of baking paper about 1 m long. Place the lamb in the centre and scatter the onion, garlic, tomatoes, feta and oregano around and over it."},{"text":"Drizzle with olive oil, then fold the paper up and over the lamb, folding and creasing the edges to seal it completely, the parcel should be airtight."},{"text":"Place the parcel on a large roasting tray and roast at 160°C for 4 to 5 hours. The lamb is done when a fork slides through the meat like butter."},{"text":"Carefully open the paper (steam will billow out). Transfer the lamb to a serving platter and let it rest for 10 minutes while you pour the cooking liquid into a small saucepan."},{"text":"Skim the fat from the surface of the liquid and warm it gently over medium heat. Season with salt, pepper and lemon juice to taste, then pour over the lamb and serve."}],"id":"dd60d5e7-974c-4014-90be-96eb5f82d2c0"},{"notes":["The coconut bread keeps wrapped for two days. Taro and pisupo are best made the day of, but can be reheated gently.","Scale up easily for bigger gatherings: add another tin of pisupo and kg of taro for every five extra people.","Let everyone build their own plate, the mains are flexible, and plenty of fruit rounds it out for those with lighter appetites.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Start the taro: bring a large pot of salted water to the boil. Add taro chunks and simmer for 25–30 minutes until tender and cooked through. Drain well and place in a serving bowl. Keep warm."},{"text":"While the taro cooks, heat oil in a large frying pan over medium heat. Add onions and cook, stirring, until soft and golden, about 8 minutes. Add corned beef, breaking it up with a wooden spoon, and stir-fry for 5–8 minutes until warmed through. Season with salt and pepper. Transfer to a serving platter."},{"text":"Make the coconut bread: preheat oven to 180°C. Sift flour, baking powder and salt into a large bowl. In another bowl, whisk together sugar, coconut milk, desiccated coconut, eggs, oil and vanilla. Pour wet ingredients into dry ingredients and stir until just combined, don't overmix."},{"text":"Divide batter between two greased 20 cm loaf tins and bake for 35–40 minutes until a skewer inserted in the centre comes out clean. Cool in tins for 5 minutes, then turn out onto a wire rack. Slice and arrange on a platter."},{"text":"Arrange all fruit on platters, keeping different types separate so people can choose."},{"text":"Set the table with pisupo, taro, coconut bread and fruit platters. Serve family-style, with everyone helping themselves."}],"id":"ad0b7c84-dd25-4930-80d0-e06496efaa96"},{"notes":["Make the sausages up to a day ahead and refrigerate on a tray before grilling.","Pork sausage casings are in the meat section at good butchers and some larger supermarkets. Soak them in water for 30 minutes before filling so they're easier to work with.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"steps":[{"text":"Mix the pork mince with coriander, garlic chives, spring onion, chilli, fish sauce, ground cumin and ground coriander in a bowl until just combined."},{"text":"Fit a sausage casing onto a sausage stuffer or piping bag fitted with a large plain nozzle. Pipe the filling into the casing, pushing gently so it's loosely packed until the sausage is plump but not tight, which stops it bursting on the grill. Tie the end."},{"text":"Heat your barbecue or grill plate to medium-high until hot and sizzling when a little oil hits it, and oil the grates."},{"text":"Coil the sausage onto the hot grill. Cook for 12 minutes, turning every couple of minutes to colour all sides evenly. The casing should be dark brown and crackling, and the meat cooked through when you press it."},{"text":"Transfer to a plate and let it rest for a minute. Serve with sticky rice, lime wedges and fresh coriander and chilli on the side."}],"id":"54b403a5-a55c-4609-93d2-ee7ab4f63f18"},{"steps":[{"text":"Bring a large pot of salted water to a boil. Add the greens in batches if needed, stirring so they wilt evenly."},{"text":"Simmer until the greens are completely tender, about 10–15 minutes. The water should taste like the sea."},{"text":"Drain in a colander, gently pressing out excess water with the back of a spoon, don't squeeze them dry."},{"text":"Divide the warm greens among plates. Drizzle each serving generously with olive oil, then squeeze lemon juice over the top. Season with salt to taste and serve warm or at room temperature."}],"id":"9512b52b-111f-4b0c-a8cd-3757cc951cdd"},{"notes":["Make it the day before, it thickens as it sits and tastes even better reheated. Add a splash of stock when you warm it up.","Use any crusty bread: sourdough, ciabatta, or even that discounted loaf from the Central Market."],"id":"c24b4848-2d14-4d96-a6eb-6f0f24ef091a"},{"notes":["Make the kebab mixture up to 2 hours ahead and chill until ready to cook.","If you don't have metal skewers, use wooden ones soaked in cold water for 30 minutes.","A cast iron pan works brilliantly for the high heat and even browning.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"id":"8d03a9f0-a4c9-462d-a30f-f5a64fdb951e"},{"notes":["Make the sambal paste up to a day ahead and store in a jar in the fridge, it keeps well and the flavours deepen.","For extra richness, use coconut oil instead of neutral oil for the sambal.","If you prefer it milder, use fewer dried chillies or remove more seeds; if you like serious heat, add an extra fresh chilli."],"id":"fa4846c5-6ab8-4002-aa67-f09408cb8110"},{"notes":["Haleem improves overnight: make it the day before, cool and store in the fridge, then gently reheat and add fresh crispy onions and ginger before serving.","If using a slow cooker, use the same ingredients and cook on low for 8 hours, stirring halfway through. The texture will be slightly looser, add a little less stock if using this method.","For a leaner dish, use lamb shoulder or goat instead of beef; cooking time stays the same.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Heat 3 tbsp ghee in a large heavy-based pot over medium heat. Working in batches, brown the beef on all sides, 8–10 minutes total. Set aside."},{"text":"In the same pot, add the diced onion and cook, stirring, until soft and golden, about 5 minutes. Add the garlic and ginger, cook for 1 minute until fragrant."},{"text":"Add cumin, coriander, garam masala, turmeric and cayenne. Stir constantly for 1 minute to bloom the spices."},{"text":"Return the beef to the pot. Add the crushed tomatoes and stir well. Cook for 2 minutes."},{"text":"Add the brown lentils, split chickpeas, stock and salt. Stir to combine. Bring to a boil, then reduce heat to low, cover with a lid slightly ajar, and simmer gently for 2½ to 3 hours, stirring occasionally to prevent sticking. The meat should fall apart, the lentils dissolve, and the mixture thicken into a porridge-like consistency. If it's too thick, add more water; if too thin, simmer uncovered toward the end."},{"text":"Taste and adjust salt and spice. The haleem should be creamy and almost paste-like, with no visible lentil pieces, break up any remaining chunks with a wooden spoon."},{"text":"About 15 minutes before serving, prepare the garnish. Heat 2 tbsp ghee in a small pan over medium heat. Add the sliced onion and cook, stirring often, until deep golden and crispy, about 8–10 minutes. Add the ginger matchsticks and cook for 1 minute."},{"text":"Spoon the haleem into bowls, top generously with the crispy onions and ginger, scatter with fresh coriander if using, and serve with lemon wedges on the side. Pour any remaining ghee and pan juices over the top."}],"id":"0b232b0e-6632-4911-ac21-f7dc1fa928c9"},{"notes":["Make ahead: shape the stuffed breads the night before, cover and refrigerate, then bring to room temperature and bake the next morning.","Swap the feta for any cheap cheese on sale, white cheddar or halloumi both work well.","Leftover bread keeps wrapped in foil for 2 days and reheats beautifully in a dry pan."],"id":"c3a2ca71-85e3-4976-bb9a-5e205ac4c701"},{"notes":["Use beef or chicken stock depending on what you have, both work just as well.","If you have fresh Vietnamese herbs like Thai basil or Vietnamese mint, use those instead of or alongside the coriander and dill.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"steps":[{"text":"Heat the oil in a large pot over medium-high heat. Add the beef mince, breaking it up as it cooks, until no longer pink, about 4 minutes. Drain any excess fat if needed."},{"text":"Add the onion and garlic, stirring until fragrant, about 1 minute."},{"text":"Add the tomato chunks and stir to combine, cooking for 2 minutes."},{"text":"Pour in the stock and bring to a simmer until the broth is bubbling gently. Add the fish sauce and sugar, stirring to combine."},{"text":"Simmer for about 10 minutes, until the tomato is soft and the broth is flavourful. Taste and adjust seasoning with salt and white pepper as needed."},{"text":"Ladle into bowls and serve hot, topped with fresh coriander and dill if using."}],"id":"9f670f96-31de-4b90-99fc-cef224a78623"},{"notes":["The romesco keeps for three days, covered, in the fridge. Make it ahead if you like.","If you can't find calcots, any large spring onion works, the charring is what matters."],"steps":[{"text":"Char the red capsicums directly over a gas flame or under a hot grill, turning often, until the skin is blackened all over, about 10 minutes. Place in a plastic bag for 5 minutes to steam, then peel away the charred skin. Discard the seeds."},{"text":"While the capsicums cool slightly, toast the bread in a dry pan over medium heat until golden, about 2 minutes each side. Tear into pieces."},{"text":"In a mortar or food processor, pound or blitz the hazelnuts with the garlic and toasted bread until you have a rough paste."},{"text":"Add the peeled capsicums and pound or pulse until you have a chunky sauce. Stir in the vinegar and olive oil. Taste and add salt. The romesco should be thick but spoonable."},{"text":"Trim the calcots, leaving the white and pale green parts. Rinse well."},{"text":"Heat a grill pan or cast-iron frying pan over high heat. Brush the calcots lightly with olive oil and place on the hot pan in a single layer. Char, turning occasionally, until the outside is blackened and the inside is tender, about 12–15 minutes. Work in batches if needed."},{"text":"Transfer the charred calcots to a serving plate. Sprinkle lightly with salt. Serve warm with the romesco sauce for dipping."}],"id":"4749620e-6af2-434e-b8bd-05e8b5ad78f6"},{"notes":["Caponata is best made a day or two ahead, the flavours deepen and marry together. Store in an airtight container in the fridge for up to a week.","Serve it at room temperature or cold, as a side dish, on bruschetta, or alongside grilled fish. Some families add a handful of pine nuts, try a small handful if you like."],"steps":[{"text":"Heat 2 tbsp of the olive oil in a large frying pan over medium-high heat. Working in batches so the eggplant isn't crowded, cook until golden on all sides, about 3–4 minutes per batch. Transfer to a plate as you go. Add the remaining oil if needed."},{"text":"In the same pan, reduce the heat to medium and cook the onion, stirring, until soft and golden, about 5 minutes. Add the garlic and cook for another minute, until fragrant."},{"text":"Stir in the tomato paste and cook for 1 minute. Pour in the crushed tomatoes, vinegar and sugar. Bring to a gentle simmer."},{"text":"Return the eggplant to the pan along with the olives and capers. Stir well. Simmer, uncovered, for 20–25 minutes, stirring occasionally, until the eggplant is very tender and the sauce has thickened and darkened slightly. The flavours should be balanced, sweet, sour and savoury all at once."},{"text":"Taste and adjust the salt, pepper, vinegar or sugar as needed. Serve at room temperature or cold, scattered with fresh parsley if you like."}],"id":"d1197ff0-fcb6-4479-902d-5df622a787ce"},{"notes":["Make sure to use waxy potatoes, floury ones will fall apart. Unpeeled skin holds them together better.","Serve warm or at room temperature, but not cold. The flavours are best when the potatoes are still warm enough to absorb the dressing.","This keeps for a few days, covered, in the fridge. Warm gently before serving again."],"id":"d526568c-d106-47f4-95b5-2a64e4f04e0b"},{"notes":["Store in an airtight tin for up to three days; the custard will firm up further and the flavour will deepen.","If you don't have baking beans, use dried rice or lentils. Make sure the pastry is fully blind-baked or it will be soggy.","For a neater slice, chill the tart for at least 2 hours before serving.","Food safety: The eggs are cooked until just set. For pregnant women, young children, older people or anyone with a weakened immune system, cook them until firm all the way through."],"steps":[{"text":"Make the pastry: rub the cold butter into the flour and salt until it resembles fine breadcrumbs. Mix the egg yolk with the caster sugar and cold water, then stir into the flour mixture until just combined. Knead gently to bring the dough together, wrap in plastic and refrigerate for 20 minutes."},{"text":"Preheat the oven to 180°C. Roll out the pastry between two sheets of baking paper to fit a 23 cm loose-bottomed tart tin. Press it gently into the tin and prick the base with a fork. Line with baking paper and fill with baking beans, then bake blind for 12 minutes. Remove the beans and paper, and bake for another 3 minutes until pale golden."},{"text":"While the pastry bakes, warm the milk with the cinnamon stick over medium heat until steaming, then remove from the heat and let it infuse for 5 minutes. Remove the cinnamon stick and cool slightly."},{"text":"Whisk the eggs with the sugar until pale and thick, about 3 minutes. Sift the cornflour, flour and salt together, then fold into the eggs. Slowly pour in the warm milk, stirring constantly to avoid lumps. Stir in the vanilla extract."},{"text":"Strain the custard through a fine sieve into the warm pastry case, pushing gently through any remaining lumps. Bake for 20 to 25 minutes, until the custard is just set but still trembling slightly in the centre, it will set as it cools."},{"text":"Remove from the oven and let the tart cool completely in the tin. Dust generously with ground cinnamon just before serving."}],"id":"f6f22e7c-fb13-4462-a1ea-f5b1a4a01c12"},{"notes":["Make it a day ahead and reheat gently, the flavours deepen. Just prepare the tempering fresh before serving.","If your pumpkin is watery, simmer a little longer to reduce the liquid to a proper sauce.","Erisseri freezes well for up to a month; thaw and reheat on the stove."],"steps":[{"text":"Toast the coriander seeds, cumin seeds, cloves, cardamom pod and dried red chillies in a dry pan over medium heat, shaking constantly, until fragrant (about 2 minutes). Tip into a bowl and let cool slightly, then grind to a fine powder. Stir in the jaggery."},{"text":"Heat 1 tbsp of the coconut oil in a heavy-bottomed pot over medium heat. Add the pumpkin and green beans, and fry, stirring gently, for 5 minutes until they start to soften at the edges."},{"text":"Sprinkle over the ground spice mixture and turmeric, stir well, and cook for another 2 minutes to let the spices coat everything."},{"text":"Pour in the coconut milk and add enough water so the vegetables are just covered. Bring to a gentle simmer and cook, uncovered, for 20–25 minutes until the pumpkin is completely tender and breaks easily with a spoon, and the beans are soft. Stir occasionally and watch the liquid, it should reduce to a creamy sauce that coats the vegetables."},{"text":"Taste and adjust salt. The curry should taste warm and mellow, with no raw spice edges."},{"text":"Just before serving, heat the remaining coconut oil in a small pan over medium-high heat. When it shimmers, add the mustard seeds and a few curry leaves. Let them crackle and pop for about 30 seconds until the seeds finish jumping and the leaves darken slightly. Pour this tempering (tadka) over the curry and stir through. Serve hot with rice."}],"id":"772ae615-ef9a-4dff-bda1-0472bdab71bd"},{"notes":["If you can't find dried oyster mushrooms, use 100 g dried shiitake instead, or a mix of any dried Chinese mushrooms you have on hand.","The chicken must be cooked through (75°C at the thickest part); check with an instant-read thermometer if unsure.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone. Cook mussels, clams and pipis only if they are alive and tightly closed (or close when tapped), and discard any that stay shut after cooking."],"steps":[{"text":"Soak the dried shiitake and oyster mushrooms in 250 ml hot water for 10 minutes until softened. Drain, reserving 125 ml of the soaking liquid. Trim the shiitake stems and halve both types of mushrooms."},{"text":"Pat the chicken breasts dry and place them on a shallow steaming plate that fits in your wok or steamer. Scatter the mushrooms around and under the chicken. Tuck the ginger slices and spring onion pieces beneath and around the chicken."},{"text":"In a small bowl, whisk the soy sauce, sesame oil, neutral oil, and reserved mushroom liquid. Pour evenly over the chicken and mushrooms. Season lightly with salt, the soy is already salty."},{"text":"Fill your wok or steamer base with water so it comes to about 5 cm deep. Bring to a rolling boil over high heat until the water is bubbling vigorously and steam is billowing. Place the steaming plate inside on a stand or trivet, making sure the plate doesn't touch the water."},{"text":"Cover and steam for 12 minutes on high heat. The chicken is done when a skewer inserted into the thickest part meets no resistance, and the juices run clear."},{"text":"Carefully remove the plate using tongs or oven mitts, the steam is hot, once the chicken is cooked through with no pink and the mushrooms are tender. Serve hot in the steaming dish, spooning the aromatic broth over the chicken and mushrooms. Pour any remaining broth into a small bowl to drizzle over rice."}],"id":"6be10260-6be0-4025-a8d4-b533551939ec"},{"notes":["If you can find pandan extract, use a tsp in one portion instead of food colouring for authentic flavour. Gula melaka (coconut sugar) can replace caster sugar for a deeper flavour.","Each layer must set properly before the next, don't rush this. If you pour the next layer onto a runny layer, the colours will muddy.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Preheat the oven to 180°C. Line an 8 × 8 inch square tin with baking paper, letting it hang over the sides."},{"text":"Mix desiccated coconut, coconut milk, caster sugar, plain flour, baking powder, salt and eggs in a bowl until smooth. Divide the mixture into 3 or 4 portions and add a few drops of food colouring to each portion (or leave some plain for white layers), stirring well. Keep each colour in a separate bowl."},{"text":"Pour the first colour into the prepared tin and spread evenly to fill the bottom. Bake for 8 to 10 minutes until just set but still soft, it should not be completely firm."},{"text":"Pour the second colour slowly over the first layer and bake again for 8 to 10 minutes until set."},{"text":"Repeat with the remaining colours, baking each layer for 8 to 10 minutes, until all layers are done."},{"text":"Remove from the oven and let cool completely in the tin on a wire rack, about 30 minutes. The cake should be cool before you try to remove it."},{"text":"Once cool, use the baking paper to lift the cake out of the tin. Cut into small squares with a sharp, lightly oiled knife."},{"text":"Store in an airtight container at room temperature for up to 3 days."}],"id":"ec9d3a5b-e766-4852-9284-f133fa1e734a"},{"notes":["Charcoal or hardwood fire makes a big difference to the flavour. If using a gas barbecue, crank it high and let it preheat for 10 minutes.","Don't move the meat around, let it sit and develop that dark, caramelised crust. That's where the flavour is.","Serve with black beans (feijão), white rice, and farofa, as it's served in Brazil.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Build your fire in a churrasco grill or barbecue, using charcoal or wood. Let it burn down to glowing coals, you want high, consistent heat, not flames. This should take about 15 to 20 minutes."},{"text":"Pat the beef, pork and chicken completely dry with paper towels. This helps them get a proper crust."},{"text":"Oil your grill grates well to stop sticking, then place them about 10 cm above the coals, once the coals are glowing red and covered in a light grey ash, with no flames, and the grates are smoking hot."},{"text":"Season the beef and pork generously with coarse rock salt on both sides just before they hit the grill. Place them directly on the hot grates and cook without moving them for 4 to 5 minutes, until a dark crust forms. Flip, salt the other side, and cook for another 4 to 5 minutes. The meat should be hot inside (use a meat thermometer: 63°C for medium-rare beef, 70°C for pork)."},{"text":"Season the chicken thighs with rock salt and place skin-side down on the grill. Cook for 6 to 7 minutes until the skin is golden and crispy, then flip. Cook for another 6 to 7 minutes until cooked through (75°C inside)."},{"text":"Rest all the meat on a warm plate for 5 minutes before serving. Drizzle with any pan juices, and serve hot with your favourite side, beans, rice, or farofa all work bem (well)."}],"id":"4a7c477b-6d1a-43a9-adbe-60e0eaaa0c8f"},{"diets":["vegetarian","vegan","no-gluten","no-dairy"],"steps":[{"text":"Heat the oil in a large pot over medium-high heat. Add the onion and cook, stirring, until soft and translucent, about 4 minutes."},{"text":"Stir in the garlic and cook for 30 seconds until fragrant, then add the tomatoes. Simmer for 5 minutes, stirring occasionally, until the tomatoes break down."},{"text":"Add the kidney beans, corn, potato and water. Bring to a simmer, then reduce heat to medium and cook until the potato is tender when pierced with a knife and the liquid has thickened slightly."},{"text":"Cook, stirring occasionally, until the potato is tender, about 12 minutes. The mixture should be thick and saucy."},{"text":"Season with salt and pepper to taste. Serve hot, scattered with fresh coriander if you like."}],"id":"21e02d78-bdbe-4533-bcf7-588a5f521f16"},{"notes":["Make a day ahead: braise the oxtail, cool completely, then refrigerate overnight. The fat will set on top and you can lift it off easily. Reheat gently on the stove before serving, the flavour only improves.","Serve with creamy mash, crusty bread or buttered rice to soak up every drop of gravy.","Food safety: Slow-cooked meat is safe once it is tender and the centre has reached at least 75°C."],"id":"ba018a4c-670a-43af-a57d-aea9cac0d145"},{"notes":["Use any leftover roasted or braised meat, beef, pork, lamb or even chicken all work well. Cold roast is traditional.","Stovies keep well; reheat gently with a splash of stock if needed, or it makes a good cold lunch the next day."],"steps":[{"text":"Heat the oil or dripping in a large heavy pot over a medium heat. Add the sliced onions and cook, stirring often, until soft and golden, about 8 minutes."},{"text":"Layer half the potato slices on top of the onions. Scatter the meat over the potatoes, then top with the remaining potatoes."},{"text":"Pour the stock over everything. Sprinkle with thyme, salt and pepper. Bring to a simmer, then reduce the heat to low and cover with a lid, cooking until the potatoes are tender and starting to break down into the stock."},{"text":"Cook gently for 30 to 35 minutes, until the potatoes are tender and have broken down slightly and the liquid has reduced to a thick, creamy sauce. Stir gently a couple of times during cooking."},{"text":"Taste and adjust the seasoning. Serve warm, straight from the pot if you're not bothered with washing extra dishes."}],"id":"362c5c74-eb36-4c22-8924-ce073b8d3b37"},{"notes":["The escovitch tastes even better made an hour or two ahead and served at room temperature.","Any firm white fish works, ask the fishmonger what's fresh that day.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"id":"eab04f11-0f4a-47b3-9016-93402e1b23e4"},{"notes":["The ras keeps in the fridge for up to 2 days covered. Make the puri just before serving so it's hot and crisp.","Use the ripest, sweetest mangoes you can find, Alphonso, Kesar or another fragrant variety work best.","If you don't have Greek yoghurt, use thick plain yoghurt or even mascarpone for a richer version."],"steps":[{"text":"Cut the mangoes into chunks and blend smooth in a food processor or blender. Pass through a fine sieve if you prefer it completely smooth; otherwise leave it rustic, both are good. You want about 500 ml of pulp. If your mangoes are very fibrous, sieve it."},{"text":"Whisk the Greek yoghurt, caster sugar, cardamom powder and salt together in a large bowl until the sugar dissolves completely."},{"text":"Add the mango pulp to the yoghurt mixture and fold together gently until just combined. Taste and add the lemon juice if the mangoes are very sweet. Chill the ras while you make the puri."},{"text":"To make the puri dough: mix the flour and salt in a bowl. Make a well in the centre, add the oil and warm water, and mix with your fingers until a soft, slightly sticky dough forms. Knead lightly for 2 minutes until smooth."},{"text":"Let the dough rest for 10 minutes covered with a damp cloth. Divide into 8 equal pieces and roll each into a ball."},{"text":"On a lightly oiled surface, roll each ball into a thin disc, about 10 cm across. Heat 3 cm of neutral oil in a wide, deep pan to 190°C (a piece of dough should float and puff immediately). Carefully slide one puri into the hot oil and press it down gently with the back of a slotted spoon, it should puff up within seconds. Flip and cook the other side until golden, about 1 minute total. Drain on paper towel. Repeat with the remaining dough."},{"text":"Serve the chilled ras in bowls or small glasses, with the hot puri on the side for dipping or tearing into pieces and stirring through."}],"id":"c452364f-960d-437c-bc3b-84d226ba8682"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;